const TaleManager = require ('../../../TaleManager');

const debugInformation = ({Ponytail}) => {
  // console.log ('Ponytail debug', Ponytail);
};

module.exports = function extendComponent (
  componentIdentifier,
  componentCreator
) {
  const ComponentTale = TaleManager.getTale (componentIdentifier);
  const {Component, extensionCount, taleOriginName} = ComponentTale;
  const ComponentTaleOrigin = TaleManager.getTale (taleOriginName);

  const newComponent = componentCreator ({
    componentIdentifier,
    [taleOriginName]: ComponentTaleOrigin.Component,
    [componentIdentifier]: !!Component
      ? ComponentTaleOrigin.Component
      : Component,
    ComponentExtentionCount: extensionCount,
  });

  ComponentTale.setComponent (newComponent);
  debugInformation ({Ponytail: this});
};
